const data = $json;
const errors = [];
if (!Array.isArray(data.placed)) errors.push("placed must be an array");
if (!Array.isArray(data.unplaced)) errors.push("unplaced must be an array");
if (typeof data.violations_count !== "number") errors.push("violations_count must be a number");
return [{json:{...data, contract_valid: errors.length === 0, contract_errors: errors}}];

const unplaced = Array.isArray($json.unplaced) ? $json.unplaced : [];
const conflicts = unplaced.map(item => ({
  course_id: item.course_id,
  code: item.code || item.course || ("COURSE-" + item.course_id),
  title: item.title || "Untitled course",
  reason_code: item.reason_code || "OTHER",
  detail: item.detail || "No placement detail provided"
}));
return [{ json: { status: $json.status, success: $json.success, conflicts, violations_count: $json.violations_count, verification_errors: $json.verification_errors || [] } }];

const placed = Array.isArray($json.placed) ? $json.placed : [];
const rows = placed.map(item => "<tr><td>" + (item.course ?? "") + "</td><td>" + (item.title ?? "") + "</td><td>" + (item.day ?? "") + "</td><td>" + (item.time ?? "") + "</td><td>" + (item.room ?? "") + "</td></tr>").join("");
const html = "<!doctype html><html><head><meta charset=\"utf-8\"><title>Course Timetable</title><style>body{font-family:Arial,sans-serif;margin:32px}table{border-collapse:collapse;width:100%}th,td{border:1px solid #ccc;padding:8px;text-align:left}th{font-weight:700}</style></head><body><h1>Course Timetable</h1><p>Placed: " + placed.length + " | Unplaced: 0</p><table><thead><tr><th>Course</th><th>Title</th><th>Day</th><th>Time</th><th>Room</th></tr></thead><tbody>" + rows + "</tbody></table></body></html>";
return [{ json: { status: "SUCCESS", placed_count: placed.length, unplaced_count: 0, html } }];
